package com.mentalmadad.entity;
import com.mentalmadad.entity.enums.*; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.*;
@Entity @Table(name="appointments") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id",nullable=false) private User patient; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="doctor_id",nullable=false) private Doctor doctor; @Column(name="appointment_date",nullable=false) private LocalDate appointmentDate; @Column(name="start_time",nullable=false) private LocalTime startTime; @Column(name="end_time",nullable=false) private LocalTime endTime; @Enumerated(EnumType.STRING) @Column(nullable=false) private AppointmentType type; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private AppointmentStatus status=AppointmentStatus.SCHEDULED; private String notes; @CreationTimestamp private LocalDateTime createdAt; @UpdateTimestamp private LocalDateTime updatedAt; }
